#!/bin/bash
# solve_and_cache.sh - Plate-solve FITS images and cache WCS crop parameters
#
# Usage: ./solve_and_cache.sh
#
# Runs solve-field on each test image (if not already cached), then uses
# wcs-rd2xy to find the pixel coordinates of the target galaxy center.
# Results are written to reference/<name>_crop.txt for the C++ test to read.

set -e

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
REF_DIR="$SCRIPT_DIR/reference"
mkdir -p "$REF_DIR"

SOLVE_FIELD=$(which solve-field)
WCS_RD2XY=$(which wcs-rd2xy)
WCSINFO=$(which wcsinfo)

if [ -z "$SOLVE_FIELD" ] || [ -z "$WCS_RD2XY" ] || [ -z "$WCSINFO" ]; then
    echo "ERROR: astrometry.net tools not found (need solve-field, wcs-rd2xy, wcsinfo)"
    exit 1
fi

# Target definitions: name, FITS path, RA (deg), Dec (deg), diameter (arcmin), [RA hint, Dec hint, radius hint]
solve_target() {
    local name="$1"
    local fits="$2"
    local target_ra="$3"
    local target_dec="$4"
    local diameter_arcmin="$5"
    local hint_ra="$6"
    local hint_dec="$7"
    local hint_radius="$8"

    local cache="$REF_DIR/${name}_crop.txt"
    local tmpdir="/tmp/solve_${name}"

    if [ -f "$cache" ]; then
        echo "$name: cached crop parameters already exist at $cache"
        cat "$cache"
        return 0
    fi

    if [ ! -f "$fits" ]; then
        echo "$name: SKIP - $fits not found"
        return 0
    fi

    echo "$name: plate-solving $fits ..."
    mkdir -p "$tmpdir"

    local solve_args="-z2 -O -D $tmpdir -o $name --no-plots --crpix-center"
    if [ -n "$hint_ra" ] && [ -n "$hint_dec" ] && [ -n "$hint_radius" ]; then
        solve_args="$solve_args -3 $hint_ra -4 $hint_dec -5 $hint_radius"
    fi
    solve_args="$solve_args -L 0.5 -H 3.0 -u arcsecperpix"

    $SOLVE_FIELD $solve_args "$fits" 2>&1 | grep -E "^Field|solved|pixel scale"

    local wcs="$tmpdir/${name}.wcs"
    if [ ! -f "$wcs" ]; then
        echo "$name: ERROR - plate solve failed"
        return 1
    fi

    # Get pixel coordinates of target center
    # wcs-rd2xy output: "RA,Dec (ra, dec) -> pixel (x, y)"
    local rd2xy_out
    rd2xy_out=$($WCS_RD2XY -w "$wcs" -r "$target_ra" -d "$target_dec")
    local center_x center_y
    center_x=$(echo "$rd2xy_out" | sed 's/.*pixel (\([0-9.]*\),.*/\1/')
    center_y=$(echo "$rd2xy_out" | sed 's/.*pixel ([0-9.]*, \([0-9.]*\)).*/\1/')

    # Get pixel scale
    local scale
    scale=$($WCSINFO "$wcs" | grep '^pixscale ' | awk '{print $2}')

    echo "$name: center=($center_x, $center_y) scale=$scale arcsec/pix diameter=$diameter_arcmin arcmin"

    cat > "$cache" <<EOF
# Plate-solved crop parameters for $name
# Generated by solve_and_cache.sh
center_x $center_x
center_y $center_y
arcsec_per_pixel $scale
diameter_arcmin $diameter_arcmin
EOF

    echo "$name: wrote $cache"
    cat "$cache"
}

# M51 (NGC 5194): RA=13h29m52.7s=202.4696° Dec=+47°11'43"=47.1953° diameter~11'
solve_target "m51" \
    "/Users/jonathan/Downloads/M51_NGC5194-RGB-session_1.fits" \
    202.4696 47.1953 11.0

echo ""

# M101 (Pinwheel): RA=14h03m12.6s=210.8525° Dec=+54°20'57"=54.3492° diameter~29'
solve_target "m101" \
    "/Users/jonathan/Downloads/M101_stacked.fits" \
    210.8525 54.3492 29.0 \
    210.8525 54.3492 5

echo ""
echo "Done."
